```ts
interface CAPA {
  id: string;
  description: string;
  evidence?: string;
  impact?: string;
  rootCause?: string;
  correctiveAction?: string;
  preventiveAction?: string;
  owner?: string;
  status?: string;
  createdAt?: string;
  updatedAt?: string;
}
```

